const KEY='sevenki-otherworld-invasion-v1';
export function cleanContinuation(raw={}){const missions={};for(const m of CONTINUATION){const r=raw?.missions?.[m.id]||{};missions[m.id]={completed:r.completed===true,checkpoint:Number.isInteger(r.checkpoint)?Math.max(0,Math.min(m.steps.length-1,r.checkpoint)):0,time:Number.isFinite(r.time)?Math.max(0,r.time):0};}return {version:1,missions,skills:missions[1401].completed?['kaioken','genki']:[]};}
export function readContinuation(){try{return cleanContinuation(JSON.parse(localStorage.getItem(KEY)||'{}'));}catch{return cleanContinuation();}}
export function continuationUnlocked(id,p=readContinuation(),raditz=readRaditz()){const i=CONTINUATION.findIndex(m=>m.id===id);return i>=0&&(i===0?raditz.completed:p.missions[CONTINUATION[i-1].id].completed);}
export function saveContinuation(id,checkpoint,time,completed=false){const p=readContinuation();if(!p.missions[id])return {saved:false};const old=p.missions[id];p.missions[id]={completed:old.completed||completed,checkpoint:completed?0:checkpoint,time:completed?0:time};const progress=cleanContinuation(p);try{localStorage.setItem(KEY,JSON.stringify(progress));return {saved:true,progress};}catch{return {saved:false,progress};}}
